"""All financial arithmetic lives here. Integer cents at rest, Decimal for ratios."""from collections import defaultdictfrom datetime import date, timedeltafrom decimal import Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_CEILINGCATEGORIES = {    "Income",    "Rent",    "Groceries",    "Restaurants",    "Transportation",    "Subscriptions",    "Entertainment",    "Shopping",    "Gambling",    "Savings",    "Other",}DISCRETIONARY = {"Restaurants", "Entertainment", "Shopping", "Gambling", "Other"}def cents(value) -> int:    try:        amount = Decimal(str(value))        if not amount.is_finite() or abs(amount) > Decimal("10000000"):            raise ValueError("Amount must be finite and at most $10,000,000.")        if amount != amount.quantize(Decimal("0.01")):            raise ValueError("Amounts must have at most two decimal places.")        return int((amount * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))    except (InvalidOperation, TypeError) as exc:        raise ValueError("Invalid monetary amount.") from excdef dollars(value: int) -> float:    return float(Decimal(value) / 100)def percent(numerator, denominator):    return (        float((Decimal(numerator) * 100 / Decimal(denominator)).quantize(Decimal("0.1")))        if denominator > 0        else None    )def goal_days(remaining: int, monthly: int):    if remaining <= 0:        return 0    if monthly <= 0:        return None    return int((Decimal(remaining) * 30 / monthly).to_integral_value(rounding=ROUND_CEILING))def projected_date(as_of, days):    if days is None or days > (date.max - as_of).days:        return None    return str(as_of + timedelta(days=days))def impact(price: int, available: int, target: int, saved: int, monthly: int, as_of: date):    remaining = max(0, target - saved)    # Baseline assumes the planned monthly contribution continues. Buying diverts    # purchase dollars from that plan; preserving them retains the baseline.    baseline = goal_days(remaining, monthly)    buying = goal_days(remaining + price, monthly) if remaining else 0    return {        "price": dollars(price),        "budget_percent": percent(price, available),        "available": dollars(available),        "within_budget": price <= available,        "goal_remaining": dollars(remaining),        "baseline_days": baseline,        "buying_days": buying,        "delay_days": buying - baseline if buying is not None and baseline is not None else None,        "baseline_date": projected_date(as_of, baseline),        "buying_date": projected_date(as_of, buying),        "monthly_contribution": dollars(monthly),    }def recurring(transactions, as_of=None):    groups = defaultdict(list)    for t in transactions:        if as_of and not str(as_of - timedelta(days=90)) <= t["date"] <= str(as_of):            continue        if t["amount_cents"] < 0 and t["category"] == "Subscriptions":            groups[t["merchant"].strip().casefold()].append(t)    result = []    for rows in groups.values():        rows.sort(key=lambda r: r["date"])        months = {r["date"][:7] for r in rows}        if (            len(months) >= 2            and len(months) == len(rows)            and all(                20 <= (date.fromisoformat(b["date"]) - date.fromisoformat(a["date"])).days <= 40                for a, b in zip(rows, rows[1:])            )            and max(r["amount_cents"] for r in rows) - min(r["amount_cents"] for r in rows) <= 100        ):            result.append(                {                    "merchant": rows[-1]["merchant"],                    "monthly": dollars(-rows[-1]["amount_cents"]),                    "occurrences": len(rows),                    "reason": "One similar charge per month, 20-40 days apart, in recent history.",                }            )    return sorted(result, key=lambda r: r["monthly"], reverse=True)def rescued(events, as_of):    return {        "this_month": dollars(sum(e["amount_cents"] for e in events if e["date"][:7] == str(as_of)[:7])),        "total": dollars(sum(e["amount_cents"] for e in events)),        "projected_annual_recurring": dollars(sum(e["recurring_cents"] for e in events) * 12),        "events": [{**e, "amount": dollars(e["amount_cents"])} for e in events],    }def dashboard(transactions, events, profile, goal):    as_of = date.fromisoformat(profile["as_of"])    month = str(as_of)[:7]    rows = [t for t in transactions if t["date"][:7] == month and t["date"] <= str(as_of)]    income = sum(t["amount_cents"] for t in rows if t["category"] == "Income" and t["amount_cents"] > 0)    expenses = -sum(t["amount_cents"] for t in rows if t["amount_cents"] < 0 and t["category"] != "Savings")    transfers = -sum(t["amount_cents"] for t in rows if t["category"] == "Savings" and t["amount_cents"] < 0)    discretionary = -sum(        t["amount_cents"] for t in rows if t["amount_cents"] < 0 and t["category"] in DISCRETIONARY    )    totals = defaultdict(int)    for t in rows:        if t["amount_cents"] < 0 and t["category"] != "Savings":            totals[t["category"]] -= t["amount_cents"]    money = rescued(events, as_of)    saved = max(        0,        goal["initial_cents"]        + sum(e["amount_cents"] for e in events if profile.get("demo") or e.get("confirmed")),    )    planned = (        sum(e["amount_cents"] for e in events if not e.get("confirmed")) if not profile.get("demo") else 0    )    remaining = max(0, goal["target_cents"] - saved)    days = goal_days(remaining, goal["monthly_cents"])    trend = []    for offset in range(7, -1, -1):        start = as_of - timedelta(days=as_of.weekday() + offset * 7)        end = min(start + timedelta(days=6), as_of)        total = -sum(            t["amount_cents"]            for t in transactions            if str(start) <= t["date"] <= str(end)            and t["amount_cents"] < 0            and t["category"] in DISCRETIONARY        )        trend.append({"week": start.strftime("%b %d"), "amount": dollars(total)})    return {        "profile": profile,        "transaction_count": len(transactions),        "month_transaction_count": len(rows),        "latest_transaction": max((t["date"] for t in transactions), default=None),        "income": dollars(income),        "expenses": dollars(expenses),        "savings_transfers": dollars(transfers),        "savings_rate": percent(transfers, income),        "available": dollars(max(0, profile["budget_cents"] - discretionary)),        "over_budget": dollars(max(0, discretionary - profile["budget_cents"])),        "budget": dollars(profile["budget_cents"]),        "discretionary_spent": dollars(discretionary),        "categories": [            {"name": k, "value": dollars(v)} for k, v in sorted(totals.items(), key=lambda x: -x[1])        ],        "subscriptions": recurring(transactions, as_of),        "subscription_monthly": dollars(sum(cents(s["monthly"]) for s in recurring(transactions, as_of))),        "trend": trend,        "money_rescued": money,        "goal": {            **goal,            "saved": dollars(saved),            "saved_cents": saved,            "planned": dollars(planned),            "planned_saved": dollars(saved + planned),            "planned_progress": min(100, percent(saved + planned, goal["target_cents"]) or 0),            "target": dollars(goal["target_cents"]),            "progress": min(100, percent(saved, goal["target_cents"]) or 0),            "days": days,            "remaining": dollars(remaining),            "date": projected_date(as_of, days),            "monthly": dollars(goal["monthly_cents"]),        },    }def gambling_status(transactions, limit: int, as_of: date, proposed: int = 0):    start = as_of - timedelta(days=as_of.weekday())    rows = [        t        for t in transactions        if str(start) <= t["date"] <= str(as_of) and t["category"] == "Gambling" and t["amount_cents"] < 0    ]    spent = -sum(t["amount_cents"] for t in rows)    return {        "spent": dollars(spent),        "limit": dollars(limit),        "percent": percent(spent, limit),        "remaining": dollars(max(0, limit - spent)),        "over_by": dollars(max(0, spent + proposed - limit)),        "week_start": str(start),        "transactions": rows,    }